/**
 * @file Checks the installed runtimes against what this library was built for.
 * Ported from Blitz's `scripts/check-provider-runtimes.ts`.
 *
 * - Codex CLI version against the generated bindings (`CODEX_PROTOCOL_VERSION`).
 * - The Codex app-server protocol, generated by the installed CLI, against every
 *   method and enum value the engine uses (`CODEX_PROTOCOL_CONTRACT`).
 * - Claude Code's version and sign-in, through a no-prompt SDK probe.
 * - Each signed-in catalogue, printed; with `--expect <file.json>` ({ codex?, claude? }
 *   lists of { id, efforts }) it is compared and drift fails the check.
 *
 * No model turn is started. Exits 1 when any check finds drift.
 *
 * Usage: npm run check:runtimes -- [--ci] [--expect models.json]
 *   --ci  Treat a missing CLI or sign-in as a failure only for the protocol check;
 *         CI installs the latest CLIs without signing in.
 */

import { execFile } from "node:child_process";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { promisify } from "node:util";
import { ClaudeEngine } from "../src/claude/engine.ts";
import { CodexEngine } from "../src/codex/engine.ts";
import { CODEX_PROTOCOL_VERSION, codexVersionIncompatibility } from "../src/codex/protocol/version.ts";
import {
  CODEX_PROTOCOL_CONTRACT,
  codexProtocolProblems,
  diffModelCatalog,
  hasModelCatalogDrift,
  readCodexProtocolSurface,
  type ComparableModel,
} from "../src/compat.ts";
import type { Engine } from "../src/types.ts";

const run = promisify(execFile);
const COMMAND_TIMEOUT_MS = 30_000;
const ciMode = process.argv.includes("--ci");
const expectIndex = process.argv.indexOf("--expect");
const expectPath = expectIndex >= 0 ? process.argv[expectIndex + 1] : undefined;
const report = { lines: [] as string[], failed: false };

function note(line: string, problem = false): void {
  report.lines.push(line);
  if (problem) report.failed = true;
}

/** Runs a CLI without a shell; a missing executable is reported, not thrown. */
async function runCommand(executable: string, args: readonly string[]): Promise<{ ok: boolean; missing: boolean; output: string }> {
  try {
    const { stdout, stderr } = await run(executable, args, { timeout: COMMAND_TIMEOUT_MS });
    return { ok: true, missing: false, output: `${stdout}${stderr}` };
  } catch (error) {
    const failure = error as NodeJS.ErrnoException & { stdout?: string; stderr?: string };
    return { ok: false, missing: failure.code === "ENOENT", output: `${failure.stdout ?? ""}${failure.stderr ?? ""}` };
  }
}

async function checkCodex(directory: string, expected?: readonly ComparableModel[]): Promise<void> {
  const executable = process.env.CODEX_EXECUTABLE || "codex";
  const version = await runCommand(executable, ["--version"]);
  if (version.missing) return note("Codex: not installed", ciMode);
  const serving = version.output.match(/(\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?)/u)?.[1] ?? "";
  const incompatibility = codexVersionIncompatibility(serving, CODEX_PROTOCOL_VERSION);
  note(`Codex ${serving || "(unknown version)"}: ${incompatibility ? `UNSUPPORTED (${incompatibility})` : `supported (bindings from ${CODEX_PROTOCOL_VERSION})`}`, Boolean(incompatibility));

  const schemaDirectory = join(directory, "schema");
  const schema = await runCommand(executable, ["app-server", "generate-json-schema", "--experimental", "--out", schemaDirectory]);
  if (!schema.ok) {
    note("  Protocol: could not generate the app-server schema", true);
  } else {
    const problems = codexProtocolProblems(await readCodexProtocolSurface(schemaDirectory));
    const methods = CODEX_PROTOCOL_CONTRACT.clientRequests.length + CODEX_PROTOCOL_CONTRACT.clientNotifications.length
      + CODEX_PROTOCOL_CONTRACT.serverNotifications.length + CODEX_PROTOCOL_CONTRACT.serverRequests.length;
    if (!problems.length) note(`  Protocol: all ${methods} methods and ${Object.keys(CODEX_PROTOCOL_CONTRACT.enums).length} enums used are present`);
    else {
      note("  Protocol: DRIFT", true);
      for (const problem of problems) note(`    - ${problem}`, true);
    }
  }
  await checkEngine("  ", new CodexEngine({ executable }), expected);
}

async function checkClaude(expected?: readonly ComparableModel[]): Promise<void> {
  await checkEngine("Claude: ", new ClaudeEngine(process.env.CLAUDE_EXECUTABLE ? { executable: process.env.CLAUDE_EXECUTABLE } : {}), expected);
}

/** Sign-in and catalogue for one engine, without a model call. */
async function checkEngine(prefix: string, engine: Engine, expected?: readonly ComparableModel[]): Promise<void> {
  try {
    const availability = await engine.availability();
    const name = engine.provider === "codex" ? "Codex" : "Claude Code";
    if (!availability.ready) {
      // An unattended CI runner is never signed in; that is not drift.
      note(`${prefix}${name}${availability.version ? ` ${availability.version}` : ""}: ${availability.message}`, availability.reason === "unsupported-version" || (!ciMode && availability.reason !== "signed-out"));
      return;
    }
    if (engine.provider === "claude") note(`${prefix}Claude Code ${availability.version ?? "(unknown version)"}: supported, ${availability.message}`);
    else note(`${prefix}Sign-in: ${availability.message}`);
    const models = await engine.models();
    note(`${prefix}Models (${models.length}): ${models.map((model) => `${model.id}${model.efforts.length ? ` [${model.efforts.join("/")}]` : ""}${model.fastMode ? " fast" : ""}`).join(", ")}`);
    if (expected) {
      const drift = diffModelCatalog(expected, models);
      if (!hasModelCatalogDrift(drift)) note(`${prefix}Models match the expected list`);
      else {
        note(`${prefix}Models: DRIFT`, true);
        for (const id of drift.added) note(`    + ${id} (live only)`, true);
        for (const id of drift.removed) note(`    - ${id} (no longer served)`, true);
        for (const change of drift.changed) note(`    ~ ${change.id}: expected [${change.expected.join(", ")}], live [${change.live.join(", ")}]`, true);
      }
    }
  } catch (error) {
    note(`${prefix}could not be checked (${error instanceof Error ? error.message : String(error)})`, true);
  } finally {
    await engine.close();
  }
}

async function main(): Promise<void> {
  const expected = expectPath ? (JSON.parse(await readFile(expectPath, "utf8")) as { codex?: ComparableModel[]; claude?: ComparableModel[] }) : {};
  const directory = await mkdtemp(join(tmpdir(), "agent-engines-runtime-check-"));
  try {
    await checkCodex(directory, expected.codex);
    await checkClaude(expected.claude);
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
  console.log(report.lines.join("\n"));
  console.log(report.failed ? "\nRuntimes have drifted from what agent-engines supports." : "\nRuntimes match what agent-engines supports.");
  process.exitCode = report.failed ? 1 : 0;
}

await main();
